{"filename": "test_password.py", "content": "import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
is_strong_password = target.is_strong_password


def test_valid_exactly_eight():
    # length exactly 8 with upper, lower, digit, symbol -> True
    assert is_strong_password("Abc123!x") is True


def test_valid_longer():
    assert is_strong_password("HelloWorld123!!") is True


def test_too_short_seven():
    # has all four classes but length 7 -> False
    assert is_strong_password("Ab1!xyz") is False


def test_seven_even_more_classes():
    # 7 chars, all classes present, still too short
    assert is_strong_password("aB1!zWq") is False


def test_missing_upper():
    assert is_strong_password("abcdef1!") is False


def test_missing_lower():
    assert is_strong_password("ABCDEF1!") is False


def test_missing_digit():
    assert is_strong_password("Abcdef!g") is False


def test_missing_symbol():
    assert is_strong_password("Abcdef1g") is False


def test_empty():
    assert is_strong_password("") is False


def test_seven_all_alnum():
    # no symbol and too short
    assert is_strong_password("abcdefg") is False


def test_non_string_raises_typeerror():
    try:
        is_strong_password(12345678)
    except TypeError:
        pass
    else:
        raise AssertionError("expected TypeError for non-string")


def test_whitespace_counts_as_symbol():
    # spec: symbols are any non-alphanumeric characters; a space qualifies
    assert is_strong_password("Abc1234 ") is True


def test_only_upper_and_digit():
    assert is_strong_password("AB12AB12") is False


def test_unicode_symbol():
    # non-alphanumeric unicode char is a symbol per spec
    assert is_strong_password("Abc123#x") is True
"}

