{"filename": "test_sorted_intersection.py", "content": "import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
sorted_intersection = target.sorted_intersection


def test_basic_intersection():
    """Basic intersection returns sorted common elements."""
    assert sorted_intersection([3, 1, 2], [2, 1]) == [1, 2]


def test_no_overlap():
    """Disjoint lists produce empty intersection."""
    assert sorted_intersection([1, 2, 3], [4, 5, 6]) == []


def test_empty_lists():
    """Empty left or right produces empty intersection."""
    assert sorted_intersection([], [1, 2, 3]) == []
    assert sorted_intersection([1, 2, 3], []) == []
    assert sorted_intersection([], []) == []


def test_identical_lists():
    """Identical lists return sorted unique elements."""
    assert sorted_intersection([3, 1, 2], [3, 1, 2]) == [1, 2, 3]


def test_duplicates_in_left():
    """Duplicates in left should appear once in output (spec: 'each shared integer once')."""
    result = sorted_intersection([1, 1, 2], [1, 2])
    assert result == [1, 2], f"Expected [1, 2] but got {result}: duplicates in left not deduplicated"


def test_duplicates_in_right():
    """Duplicates in right should not cause duplicates in output."""
    result = sorted_intersection([1, 2], [1, 1, 2, 2])
    assert result == [1, 2], f"Expected [1, 2] but got {result}: duplicates in right caused extra output"


def test_duplicates_in_both():
    """Duplicates in both lists should appear once in output."""
    result = sorted_intersection([1, 1, 2, 2], [1, 2, 2])
    assert result == [1, 2], f"Expected [1, 2] but got {result}: duplicates not removed"


def test_single_element_overlap():
    """Single shared element works."""
    assert sorted_intersection([1], [1]) == [1]


def test_single_element_no_overlap():
    """No shared element."""
    assert sorted_intersection([1], [2]) == []


def test_negative_numbers():
    """Negative integers work correctly."""
    assert sorted_intersection([-3, -1, 2], [-1, 2, 5]) == [-1, 2]


def test_zero_included():
    """Zero is a valid integer."""
    assert sorted_intersection([0, 1], [0]) == [0]


def test_output_sorted_ascending():
    """Output must be sorted ascending."""
    assert sorted_intersection([5, 3, 1, 4], [4, 3, 2, 1]) == [1, 3, 4]


def test_type_error_non_list_left():
    """Non-list left raises TypeError."""
    try:
        sorted_intersection("abc", [1, 2])
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_type_error_non_list_right():
    """Non-list right raises TypeError."""
    try:
        sorted_intersection([1, 2], "abc")
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_type_error_non_int_in_left():
    """Non-int in left raises TypeError."""
    try:
        sorted_intersection([1, "two", 3], [1, 2, 3])
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_type_error_non_int_in_right():
    """Non-int in right raises TypeError."""
    try:
        sorted_intersection([1, 2, 3], [1, "two"])
        assert False, "Expected TypeError"
    except TypeError:
        pass
"}

